IF OBJECT_ID(N'Layercake.dim_local_group', N'U') IS NOT NULL
BEGIN
    IF EXISTS (SELECT 1 FROM Layercake.dim_local_group)
    BEGIN
        -- keeps the data: the table and its constraints are renamed, never dropped with rows in them
        IF OBJECT_ID(N'Layercake.dim_local_group_rolledback_MIG0032', N'U') IS NOT NULL
